export interface SignLandmarkFrame {
  rh?: (number[] | null)[] | null;
  lh?: (number[] | null)[] | null;
  pose?: (number[] | null)[] | null;
}

export interface SignRecord {
  id?: number;
  word: string;
  parts?: string[];
  frames: SignLandmarkFrame[];
  fps?: number;
  created_at?: string;
  [key: string]: any;
}

