// Dynamic cache that can also fetch newly trained tokens from backend or public/signs.json
const runtimeCache = new Map<string, SignRecord>();
let signsLoaded = false;

// Pre-fill cache with bundled signs
Object.entries(BUNDLED_SIGNS).forEach(([k, v]) => runtimeCache.set(k.toLowerCase().trim(), v));

/**
 * Fetch and synchronize latest trained signs from backend API or local public/signs.json.
 * Ensures all trained signs are immediately available in student UI offline & online.
 */
export async function syncSignsFromBackend(): Promise<Map<string, SignRecord>> {
  if (signsLoaded) return runtimeCache;

  const apiBase = (import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000').replace(/\/+$/, '');
  let fetched = false;

  // 1. Try configured backend API first
  try {
    const res = await fetch(`${apiBase}/api/signs`, { cache: 'no-store' });
    if (res.ok) {
      const remoteSigns: SignRecord[] = await res.json();
      for (const s of remoteSigns) {
        if (s && s.word) {
          runtimeCache.set(s.word.toLowerCase().trim(), s);
        }
      }
      fetched = true;
      signsLoaded = true;
    }
  } catch (_) {
    // Backend offline or unreachable
  }

  // 2. If backend wasn't reachable, load complete sign dataset from public/signs.json
  if (!fetched) {
    try {
      const staticRes = await fetch('/signs.json');
      if (staticRes.ok) {
        const staticSigns: SignRecord[] = await staticRes.json();
        for (const s of staticSigns) {
          if (s && s.word) {
            runtimeCache.set(s.word.toLowerCase().trim(), s);
          }
        }
        signsLoaded = true;
      }
    } catch (_) {
      // Rely on bundled dataset
    }
  }

  return runtimeCache;
}

/**
 * Get sign record for a word/phrase.
 * Checks bundled signs first, then tries local server.py /api/signs if available.
 */
export async function getSignRecord(word: string): Promise<SignRecord | null> {
  const norm = (word || '').toLowerCase().trim();
  if (!norm) return null;

  if (runtimeCache.has(norm)) {
    return runtimeCache.get(norm)!;
  }

  await syncSignsFromBackend();
  return runtimeCache.get(norm) || null;
}

export interface PlayableSignItem {
  word: string;
  sign: SignRecord | null;
  found: boolean;
}

/**
 * Smart Greedy Longest-Matching N-gram Tokenizer (Matching player.js on localhost:8000)
 * Prioritizes: Sentences > Multi-word Phrases (e.g. "good morning", "thank you") > Single words.
 */
export async function resolveTokensToPlayableSigns(
  tokensOrText: string[] | string
): Promise<PlayableSignItem[]> {
  await syncSignsFromBackend();

  let words: string[] = [];
  if (Array.isArray(tokensOrText)) {
    words = tokensOrText
      .join(' ')
      .toLowerCase()
      .replace(/[^a-z0-9\s'\-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .split(' ')
      .filter(Boolean);
  } else if (typeof tokensOrText === 'string') {
    words = tokensOrText
      .toLowerCase()
      .replace(/[^a-z0-9\s'\-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .split(' ')
      .filter(Boolean);
  }

  if (words.length === 0) return [];

  // Check if entire text matches directly
  const whole = words.join(' ');
  if (runtimeCache.has(whole)) {
    return [{ word: whole, sign: runtimeCache.get(whole)!, found: true }];
  }

  const results: PlayableSignItem[] = [];
  const maxNgram = 8;
  let i = 0;

  while (i < words.length) {
    let matched = false;
    const windowMax = Math.min(maxNgram, words.length - i);

    for (let len = windowMax; len >= 1; len--) {
      const candidate = words.slice(i, i + len).join(' ');
      if (runtimeCache.has(candidate)) {
        results.push({
          word: candidate,
          sign: runtimeCache.get(candidate)!,
          found: true,
        });
        i += len;
        matched = true;
        break;
      }
    }

    if (!matched) {
      const w = words[i];
      results.push({
        word: w,
        sign: runtimeCache.get(w) || null,
        found: runtimeCache.has(w),
      });
      i += 1;
    }
  }

  return results;
}

